<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Maquinaria | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><header class="admin-header"><div><p class="eyebrow">Activos operativos</p><h1>Maquinaria y mantenciones</h1><p class="setup-copy">Controla equipos, mantenciones y consumo de combustible.</p></div><a class="secondary-link" href="/">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nueva maquinaria</h2><p>Registra equipos y activos agrícolas</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_machinery"><label>Código<input name="code" required placeholder="TR-001"></label><label>Nombre<input name="name" required placeholder="Tractor principal"></label><label>Tipo<input name="machinery_type" required placeholder="Tractor"></label><label>Marca<input name="brand"></label><label>Modelo<input name="model"></label><label>Patente<input name="plate"></label><label>Horómetro<input type="number" name="meter" min="0" step="0.01"></label><label>Fundo<select name="farm_id"><option value="">Sin asignar</option><?php foreach ($farms as $farm): ?><option value="<?= (int) $farm['id'] ?>"><?= htmlspecialchars($farm['name']) ?></option><?php endforeach; ?></select></label><button class="primary-button" type="submit">Crear maquinaria</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Registrar mantención</h2><p>Preventiva o correctiva</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_maintenance"><label>Maquinaria<select name="machinery_id" required><?php foreach ($machinery as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['code'] . ' · ' . $item['name']) ?></option><?php endforeach; ?></select></label><label>Tipo<select name="maintenance_type"><option value="PREVENTIVE">Preventiva</option><option value="CORRECTIVE">Correctiva</option></select></label><label>Fecha<input type="date" name="maintenance_date" value="<?= date('Y-m-d') ?>" required></label><label>Descripción<input name="description" required></label><label>Costo<input type="number" name="cost" min="0" step="0.01"></label><label>Próxima mantención<input type="date" name="next_date"></label><button class="primary-button" type="submit">Registrar mantención</button></form></article></section><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Equipos registrados</h2><p><?= count($machinery) ?> activos</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Equipo</th><th>Tipo</th><th>Ubicación</th><th>Horómetro</th><th>Estado</th></tr></thead><tbody><?php foreach ($machinery as $item): ?><tr><td><b><?= htmlspecialchars($item['name']) ?></b><small><?= htmlspecialchars($item['code']) ?> · <?= htmlspecialchars($item['brand'] ?: 'Sin marca') ?></small></td><td><?= htmlspecialchars($item['machinery_type']) ?></td><td><?= htmlspecialchars($item['farm_name'] ?: 'Sin fundo') ?></td><td><?= number_format((float) $item['meter'], 2, ',', '.') ?></td><td><span class="status-pill status-active"><?= htmlspecialchars($item['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></article><article class="admin-panel"><header class="panel-header"><h2>Combustible</h2><p>Registro de consumo por equipo</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_fuel"><label>Maquinaria<select name="machinery_id" required><?php foreach ($machinery as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['name']) ?></option><?php endforeach; ?></select></label><label>Fecha<input type="date" name="fuel_date" value="<?= date('Y-m-d') ?>" required></label><label>Litros<input type="number" name="liters" min="0.001" step="0.001" required></label><label>Costo unitario<input type="number" name="unit_cost" min="0" step="0.01" required></label><label>Referencia<input name="reference"></label><button class="primary-button" type="submit">Registrar combustible</button></form></article></section><section class="admin-panel"><header class="panel-header"><h2>Historial de mantenciones</h2><p>Seguimiento de servicios realizados</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Fecha</th><th>Equipo</th><th>Tipo</th><th>Descripción</th><th>Costo</th><th>Próxima</th></tr></thead><tbody><?php foreach ($maintenance as $item): ?><tr><td><?= htmlspecialchars($item['maintenance_date']) ?></td><td><?= htmlspecialchars($item['machinery_name']) ?></td><td><?= htmlspecialchars($item['maintenance_type']) ?></td><td><?= htmlspecialchars($item['description']) ?></td><td>$<?= number_format((float) $item['cost'], 0, ',', '.') ?></td><td><?= htmlspecialchars($item['next_date'] ?: 'No definida') ?></td></tr><?php endforeach; ?></tbody></table></div></section></main></body></html>
